import React, { useState } from 'react';
import { FileUploader } from './FileUploader';
import { generatePDF } from './pdfGenerator';
import HardHatIcon from './HardHatIcon.svg';

function App() {
  const [file, setFile] = useState<File | null>(null);
  const [pdfUrl, setPdfUrl] = useState<string | null>(null);

  const handleFileChange = (file: File | null) => {
    setFile(file);
    setPdfUrl(null); // Clear the previous PDF
  };

  const handleGeneratePdf = async () => {
    if (!file) {
      alert('Please upload a file.');
      return;
    }

    try {
      const url = await generatePDF(file);
      setPdfUrl(url);
    } catch (error) {
      console.error('Error generating PDF:', error);
      alert('An error occurred while generating the PDF.');
    }
  };

  return (
    <div className="container mx-auto p-4">
      <h1 className="text-2xl font-bold mb-4">Manifest QR (PDF) Generator</h1>
      <FileUploader onFileChange={handleFileChange} />
      {file && (
        <div className="mt-4">
          <button
            className="bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded"
            onClick={handleGeneratePdf}
          >
            Generate PDF
          </button>
        </div>
      )}
      {pdfUrl && (
        <div className="mt-4">
          <a href={pdfUrl} target="_blank" rel="noopener noreferrer" className="text-blue-500 hover:text-blue-700">
            Download PDF
          </a>
        </div>
      )}
