// Robust header detection synonyms
const ROUTE_SYNONYMS = ['route', 'lndn', 'manifest', '#', 'driver', 'run', 'stop', 'id', 'ref', 'code', 'link', 'name', 'vehicle', 'route id', 'run number', 'tour'];
const IDC_SYNONYMS = ['idc', 'hub', 'depot', 'location', 'site', 'terminal', 'warehouse', 'center', 'branch', 'area', 'region', 'dc', 'station', 'base'];

// Helper to find header case-insensitively with better fuzzy matching
const findHeaderKey = (row: any, candidates: string[]): string | undefined => {
  const keys = Object.keys(row);
  // Try exact match first
  let found = keys.find(key => {
    const k = key.toLowerCase().trim();
    return candidates.some(c => k === c);
  });

  // Try partial match if exact fails
  if (!found) {
    found = keys.find(key => {
        const k = key.toLowerCase().trim();
        return candidates.some(c => k.includes(c));
    });
  }
  return found;
};

// Helper: Check PDF Header for Magic Bytes (%PDF-)
const isPdfFile = (buffer: ArrayBuffer): boolean => {
    if (buffer.byteLength < 5) return false;
    const arr = new Uint8Array(buffer).subarray(0, 5);
    const header = String.fromCharCode(...arr);
    return header.startsWith('%PDF-');
};

