const scanPdfForRoutes = async (
    pdfArrayBuffer: ArrayBuffer, 
    onProgress: (percent: number) => void,
    baseProgress: number,
    progressScale: number,
    shouldStop: { current: boolean }
): Promise<Map<string, number[]>> => {
    const pdfLoadingTask = pdfjsLib.getDocument(pdfArrayBuffer.slice(0));
    const pdfProxy = await pdfLoadingTask.promise;
    const totalPages = pdfProxy.numPages;
    const routeMap = new Map<string, number[]>();

    for (let i = 1; i <= totalPages; i++) {
        if (shouldStop.current) throw new Error("Process stopped by user.");

        const page = await pdfProxy.getPage(i);
        const textContent = await page.getTextContent();
        const text = textContent.items.map((item: any) => item.str).join(' ');

        const match = text.match(/(LNDN\s*\d+)/i);
        if (match) {
            const rawRoute = match[1];
            const normalizedRoute = rawRoute.replace(/\s+/g, '').toUpperCase();
            if (!routeMap.has(normalizedRoute)) {
                routeMap.set(normalizedRoute, []);
            }
            routeMap.get(normalizedRoute)?.push(i - 1); // 0-indexed
        }

        onProgress(Math.floor(baseProgress + (i / totalPages) * progressScale));
    }

    return routeMap;
};

