export const analyzeRouteAddress = async (
  routeId: string,
  idc: string,
  pdfText: string
): Promise<BusinessPackage | null> => {
  const maxRetries = 3;
  let attempt = 0;
  const baseDelay = 3000;

  while (attempt <= maxRetries) {
    try {
      const truncatedText = pdfText.slice(0, 2000);

      // Use gemini-3-flash-preview for efficiency and capability
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Analyze this delivery manifest text for Route ${routeId}. 
        Extract the delivery destination address and determine if it's a Business or Residential location.
        Text: "${truncatedText}"`,
        config: {
          systemInstruction: "You are a logistics expert. Identify delivery addresses and verify if they are commercial/business entities. Respond only with JSON.",
          responseMimeType: "application/json",
          responseSchema: {
            type: "OBJECT",
            properties: {
              isBusiness: { type: "BOOLEAN" },
              businessName: { type: "STRING" },
              address: { type: "STRING" }
            },
            required: ["isBusiness", "businessName", "address"]
          },
          tools: [{ googleSearch: {} }] // Support for finding real business info
        }
      });

      const resultText = response.text;
      if (!resultText) return null;

      const data = JSON.parse(resultText);

      let mapLink = "";
      const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (groundingChunks) {
        for (const chunk of groundingChunks) {
          if (chunk.web?.uri) {
              mapLink = chunk.web.uri;
              break;
          }
        }
      }

      return {
        route: routeId,
        idc: idc,
        isBusiness: !!data.isBusiness,
        businessName: data.businessName || "Unknown Business",
        address: data.address || "Address not found",
        mapLink: mapLink || `https://www.google.com/maps/search/${encodeURIComponent(data.address || "")}`
      };

    } catch (error: any) {
      const isRateLimit = error.status === 429;
      if (isRateLimit && attempt < maxRetries) {
          const delay = baseDelay * Math.pow(2, attempt);
          await wait(delay);
          attempt++;
          continue;
      }
      console.error(`AI Analysis failed for route ${routeId}:`, error);
      return null;
    }
  }

